def NS = 'urn:sciback:midpoint:person'
def HOY = java.time.LocalDate.now(java.time.ZoneId.of('America/Lima'))
def fecha = { v -> def s = (v == null) ? '' : basic.stringify(v).trim(); (s ==~ /\d{4}-\d{2}-\d{2}.*/) ? java.time.LocalDate.parse(s.substring(0, 10)) : null }
// Matricula vigente segun la fuente (identico a 3327): sin fecha o fin >= hoy -> 'student'.
def raw = basic.getAttributeValue(shadow, 'DATE_EXPIRY')
if (raw == null) return 'student'
def s = raw.toString().trim()
if (s.length() < 10) return 'student'
def f
try { f = java.time.LocalDate.parse(s.substring(0, 10)) } catch (Exception ex) { return 'student' }
if (!f.isBefore(HOY)) return 'student'
// Fin vencido: gracia hasta el fin efectivo que publica el template (G2; ahi vive N).
def eff = fecha(basic.getExtensionPropertyValue(focus, NS, 'studentEnrollmentEffectiveEnd'))
return (eff != null && !HOY.isAfter(eff)) ? 'student' : null
